using System;
using Supprocom.NativeAllocationManagement;
public sealed class DisposableThing : IDisposable { public void Dispose() { } }
public static class Sample { public static void Run() { using (new DisposableThing()) { NativeRegion region = new(); NativeConcurrentPool<int> pool = new(returnMemoryOnDispose: NativeMemoryReturn.ToNativeMemory); ConcurrentPooled<int> value = pool.Rent(1, static writer => writer.Fill(default!)); } } }

using System;
using Supprocom.NativeAllocationManagement;
public sealed class Sample : IDisposable { private readonly NativeConcurrentPool<int> _pool = new(returnMemoryOnDispose: NativeMemoryReturn.ToNativeMemory); private readonly NativeConcurrentPool<int> _other = new(); public void Dispose() { _other.Dispose(); } }

using Supprocom.NativeAllocationManagement;
public record Holder(NativeConcurrentPool<int> Pool);
public static class Sample { public static void Run() { NativeConcurrentPool<int> pool = new(); Holder holder = new(pool); pool.Dispose(); } }

using Supprocom.NativeAllocationManagement;
public sealed class Holder<T> { public T Value = default!; }
public static class Sample { public static void Run() { NativeConcurrentPool<int> pool = new(); Holder<NativeConcurrentPool<int>> holder = new() { Value = pool }; pool.Dispose(); } }

using Supprocom.NativeAllocationManagement;
public sealed class Holder<T> { public T Value = default!; }
public static class Sample { public static void Run() { NativeConcurrentPool<int> pool = new(); ConcurrentPooled<int> value = pool.Rent(1, static writer => writer.Fill(default!)); Holder<ConcurrentPooled<int>> holder = new(); holder.Value = value; } }

using System;
using Supprocom.NativeAllocationManagement;
public static class Sample { public static void Run() { NativeConcurrentPool<int> pool = new(); ConcurrentPooled<int> value = pool.Rent(1, static writer => writer.Fill(default!)); Action callback = () => Console.WriteLine(value.Length); } }

using System.Threading.Tasks;
using Supprocom.NativeAllocationManagement;
public static class Sample { public static async Task Run() { NativeConcurrentPool<int> pool = new(); ConcurrentPooled<int> value = pool.Rent(1, static writer => writer.Fill(default!)); await Task.Yield(); _ = value.Length; } }

using System.Collections.Generic;
using Supprocom.NativeAllocationManagement;
public static class Sample { public static IEnumerable<int> Run() { NativeConcurrentPool<int> pool = new(); ConcurrentPooled<int> value = pool.Rent(1, static writer => writer.Fill(default!)); yield return value.Length; } }

using System;
using Supprocom.NativeAllocationManagement;
public static class Sample { public static void Run() { NativeConcurrentPool<int> pool = new(); try { ConcurrentPooled<int> value = pool.Rent(1, static writer => writer.Fill(default!)); throw new InvalidOperationException(); } catch (InvalidOperationException) { } pool.Dispose(); } }

